    if all(_num(s.get(k)) for k in ("total_tokens","input_tokens","output_tokens")) and s["total_tokens"]!=s["input_tokens"]+s["output_tokens"]:
        failures.append(f"{label}: summary total_tokens != input + output")
    if not _num(s.get("wall_seconds")) or s["wall_seconds"]<0: failures.append(f"{label}: wall_seconds is missing or negative")

def _pack(pack,s,t,mode,case,label,failures):
    if not pack.complete: failures.append(f"{label}: saved actual pack is incomplete")
    if pack.manifest.outcome!="completed": failures.append(f"{label}: saved actual pack outcome is not completed")
    if str(pack.manifest.ticker).upper()!=t or pack.manifest.context_mode!=mode: failures.append(f"{label}: saved actual pack identity/mode mismatch")
    u=pack.usage
    for k in ("calls","input_tokens","output_tokens","total_tokens"):
        if not _num(getattr(u,k)) or getattr(u,k)<=0: failures.append(f"{label}: saved pack {k} is not positive recorded usage")
        if s.get(k)!=getattr(u,k): failures.append(f"{label}: summary {k} does not match the saved actual pack")
    if u.total_tokens!=u.input_tokens+u.output_tokens: failures.append(f"{label}: saved pack total_tokens != input + output")
    try:
        from .live import _deterministic_checks
        return _by_name(_deterministic_checks(case,pack,t))
    except Exception as e:
        failures.append(f"{label}: cannot recompute checks from saved actual pack: {e}"); return {}

def _judge(j,recomputed,label,failures):
    if j.get("error") is not False: failures.append(f"{label}: judge error is not false")
    if not _num(j.get("support")) or j["support"]<MIN_SUPPORT: failures.append(f"{label}: support below {MIN_SUPPORT}")
    if not _num(j.get("relevance")) or j["relevance"]<MIN_RELEVANCE: failures.append(f"{label}: relevance below {MIN_RELEVANCE}")
    if not _num(j.get("valid_citation_rate")) or j["valid_citation_rate"]<MIN_CITATION: failures.append(f"{label}: valid_citation_rate below {MIN_CITATION}")
    if j.get("semantic_valid") is not True: failures.append(f"{label}: semantic_valid is not true")
    if j.get("semantic_errors")!=[]: failures.append(f"{label}: semantic_errors is not empty")
    saved=_by_name(j.get("deterministic_checks"))
    for n in MANDATORY:
        if n not in saved: failures.append(f"{label}: mandatory deterministic check missing: {n}")
        elif saved[n].get("passed") is not True: failures.append(f"{label}: deterministic check failed: {n}")
        if recomputed:
            a=recomputed.get(n)
            if a is None or a.get("passed") is not True: failures.append(f"{label}: recomputed pack check failed: {n}")
            elif n in saved and saved[n].get("passed")!=a.get("passed"): failures.append(f"{label}: saved check disagrees with saved actual pack: {n}")

def validate_release(root,evidence_dir):
    root=Path(root).resolve(); ev=Path(evidence_dir)
    if not ev.is_absolute(): ev=root/ev
    failures=[]; checks=[]; warnings=[]; metrics={"cases":{}}
    try: current=source_fingerprint(root); checks.append(f"RELEASE_SOURCE_FINGERPRINT={current}")
    except Exception as e: current=None; failures.append(f"source fingerprint unavailable: {e}")
    from .case_registry import all_cases
    cases={c["ticker"].upper():c for c in all_cases()}; expected=set(cases)
    if not ev.is_dir():
        failures.append(f"release evidence directory missing: {ev}")
        return {"failures":failures,"checks":checks,"warnings":warnings,"metrics":metrics}
    present={p.name.upper() for p in ev.iterdir() if p.is_dir() and p.name not in {"judge","aggregate"}}
    for t in sorted(expected-present): failures.append(f"missing expected case: {t}")
    for t in sorted(present-expected): failures.append(f"unexpected case identity: {t}")
    checks.append(f"RELEASE_CASES={len(expected)}")
    arms={}
    for t,case in cases.items():
        arms[t]={}
        for mode in MODES:
            label=f"{t}/{mode}"; arm=ev/t/mode
            if not arm.is_dir(): failures.append(f"{label}: arm missing"); continue
            s=_json(arm/"summary.json",label,failures); cfg=_json(arm/"config.json",label,failures)
            pv=_json(arm/PROV,label,failures); j=_json(ev/"judge"/t/mode/"judge.json",label,failures)
            jp=_json(ev/"judge"/t/mode/PROV,label,failures)
            if not all(isinstance(x,dict) for x in (s,cfg,pv,j,jp)): continue
            _prov(pv,current,label,"run",failures); _prov(jp,current,label,"judge",failures); _summary(s,t,mode,label,failures)
            for k in ("llm_provider","quick_think_llm","deep_think_llm"):
                if not cfg.get(k): failures.append(f"{label}: config missing {k}")
            if cfg.get("llm_provider")!=pv.get("provider"): failures.append(f"{label}: config provider != run provenance provider")
            if cfg.get("quick_think_llm")!=pv.get("model") or cfg.get("deep_think_llm")!=pv.get("model"): failures.append(f"{label}: config model fields != run provenance model")
            if cfg.get("quick_think_llm")!=DEFAULT_MODEL or cfg.get("deep_think_llm")!=DEFAULT_MODEL: failures.append(f"{label}: config model is not current {DEFAULT_MODEL!r}")
            recomputed={}
            try:
                from ..evidence import EvidencePackIO
                recomputed=_pack(EvidencePackIO().import_pack(arm/"run"),s,t,mode,case,label,failures)
            except Exception as e: failures.append(f"{label}: saved actual pack cannot be loaded: {e}")
            _judge(j,recomputed,label,failures)
            arms[t][mode]={"summary":s,"config":cfg,"prov":pv,"judge":j,"jprov":jp}
        b=arms[t].get("baseline"); c=arms[t].get("compact")
        if not b or not c: continue
        if (b["prov"].get("model"),b["prov"].get("provider"))!=(c["prov"].get("model"),c["prov"].get("provider")): failures.append(f"{t}: run model/provider differ across arms")
        if _settings(b["config"])!=_settings(c["config"]): failures.append(f"{t}: settings differ across arms")
        if (b["jprov"].get("model"),b["jprov"].get("provider"))!=(c["jprov"].get("model"),c["jprov"].get("provider")): failures.append(f"{t}: judge model/provider differ across arms")
        if (b["prov"].get("model"),b["prov"].get("provider"))!=(b["jprov"].get("model"),b["jprov"].get("provider")): failures.append(f"{t}: judge provenance does not match run provenance")
        metrics["cases"][t]={"baseline_tokens":b["summary"].get("total_tokens"),"compact_tokens":c["summary"].get("total_tokens"),"baseline_wall_seconds":b["summary"].get("wall_seconds"),"compact_wall_seconds":c["summary"].get("wall_seconds"),"baseline_quality":_quality(b["judge"]),"compact_quality":_quality(c["judge"])}
    paired=[m for m in metrics["cases"].values() if None not in (m["baseline_tokens"],m["compact_tokens"],m["baseline_wall_seconds"],m["compact_wall_seconds"],m["baseline_quality"],m["compact_quality"])]
    if paired:
