        bw=sum(m["baseline_wall_seconds"] for m in paired); cw=sum(m["compact_wall_seconds"] for m in paired)
        reduction=1-ct/bt if bt>0 else None; ratio=cw/bw if bw>0 else None
        bq=sum(m["baseline_quality"] for m in paired)/len(paired); cq=sum(m["compact_quality"] for m in paired)/len(paired); drop=bq-cq
        metrics["aggregate"]={"token_reduction":reduction,"mean_quality_baseline":bq,"mean_quality_compact":cq,"mean_quality_drop":drop,"wall_ratio":ratio}
        metrics["should_targets"]={"token_reduction":{"value":reduction,"target":f">={COST_MIN}","passed":reduction is not None and reduction>=COST_MIN},"mean_quality_drop":{"value":drop,"target":f"<={QUALITY_DROP_MAX}","passed":drop<=QUALITY_DROP_MAX},"wall_ratio":{"value":ratio,"target":f"<={WALL_MAX}","passed":ratio is not None and ratio<=WALL_MAX}}
        for name,target in metrics["should_targets"].items():
            status="PASS" if target["passed"] else "FAIL"; checks.append(f"RELEASE_SHOULD {name}={target['value']} target {target['target']} {status}")
            if not target["passed"] and name!="mean_quality_drop": warnings.append(f"Should target missed: {name}={target['value']} target {target['target']}")
        if drop>QUALITY_DROP_MAX: failures.append(f"quality retention failed: mean quality drop {drop:.4f} > {QUALITY_DROP_MAX}")
    return {"failures":failures,"checks":checks,"warnings":warnings,"metrics":metrics,"source_fingerprint":current}
